package com.example.clinometer

import android.content.Intent
import android.media.MediaPlayer
import android.net.Uri
import android.os.Bundle
import android.widget.MediaController
import android.widget.TextView
import android.widget.Toast
import android.widget.VideoView
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.FileProvider
import com.google.android.material.button.MaterialButton
import java.io.File
import java.util.Locale

class TrackSessionVideoActivity : AppCompatActivity() {

    private lateinit var btnBack: MaterialButton
    private lateinit var btnExport: MaterialButton
    private lateinit var tvVideoTitle: TextView
    private lateinit var tvVideoSubtitle: TextView
    private lateinit var videoView: VideoView
    private var videoFile: File? = null
    private var pendingExportVideoFile: File? = null

    private val exportVideoLauncher = registerForActivityResult(ActivityResultContracts.CreateDocument("video/mp4")) { uri: Uri? ->
        val sourceFile = pendingExportVideoFile
        pendingExportVideoFile = null

        if (uri == null || sourceFile == null || !sourceFile.exists()) {
            if (sourceFile == null || !sourceFile.exists()) {
                Toast.makeText(this, getString(R.string.track_session_video_unavailable), Toast.LENGTH_SHORT).show()
            }
            return@registerForActivityResult
        }

        val exported = TrackSessionVideoExport.saveVideoToUri(this, sourceFile, uri)
        val messageRes = if (exported) {
            R.string.track_session_video_save_success
        } else {
            R.string.track_session_video_save_failed
        }
        Toast.makeText(this, getString(messageRes), Toast.LENGTH_SHORT).show()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_track_session_video)

        btnBack = findViewById(R.id.btnVideoBack)
        btnExport = findViewById(R.id.btnVideoExport)
        tvVideoTitle = findViewById(R.id.tvVideoPlayerTitle)
        tvVideoSubtitle = findViewById(R.id.tvVideoPlayerSubtitle)
        videoView = findViewById(R.id.videoViewSession)

        videoFile = intent.getStringExtra("video_path")
            ?.takeIf { it.isNotBlank() }
            ?.let { File(it) }

        tvVideoTitle.text = intent.getStringExtra("video_title")
            ?: getString(R.string.track_session_video_player_title)

        btnBack.setOnClickListener {
            finish()
        }
        btnExport.setOnClickListener {
            exportVideo()
        }

        bindVideo()
    }

    override fun onPause() {
        super.onPause()
        if (videoView.isPlaying) {
            videoView.pause()
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        videoView.stopPlayback()
    }

    private fun bindVideo() {
        val file = videoFile
        if (file == null || !file.exists()) {
            Toast.makeText(this, getString(R.string.track_session_video_unavailable), Toast.LENGTH_SHORT).show()
            finish()
            return
        }

        val videoUri = FileProvider.getUriForFile(this, "${packageName}.fileprovider", file)
        val mediaController = MediaController(this)
        mediaController.setAnchorView(videoView)

        videoView.setMediaController(mediaController)
        videoView.setVideoURI(videoUri)
        videoView.setOnPreparedListener { player: MediaPlayer ->
            tvVideoSubtitle.text = formatDuration(player.duration.toLong())
            player.isLooping = false
            videoView.start()
        }
        videoView.setOnErrorListener { _, _, _ ->
            Toast.makeText(this, getString(R.string.track_session_video_unavailable), Toast.LENGTH_SHORT).show()
            true
        }
    }

    private fun exportVideo() {
        val file = videoFile
        if (file == null || !file.exists()) {
            Toast.makeText(this, getString(R.string.track_session_video_unavailable), Toast.LENGTH_SHORT).show()
            return
        }

        pendingExportVideoFile = file
        exportVideoLauncher.launch(TrackSessionVideoExport.buildExportFileName(tvVideoTitle.text.toString()))
    }

    private fun formatDuration(durationMs: Long): String {
        val totalSeconds = (durationMs.coerceAtLeast(0L) / 1000L)
        val minutes = totalSeconds / 60L
        val seconds = totalSeconds % 60L
        return String.format(Locale.getDefault(), "%d:%02d", minutes, seconds)
    }
}
